entities.syntax:
typedef struct _PERF_COUNTER_HEADER {
    ULONG dwStatus;
    PerfCounterDataType dwType;
    ULONG dwSize;
    ULONG Reserved;
} PERF_COUNTER_HEADER, *PPERF_COUNTER_HEADER;

ULONG PerfDecrementULongCounterValue(
[in] HANDLE                    Provider,   [in] PPERF_COUNTERSET_INSTANCE Instance,   [in] ULONG                     CounterId,
[in] ULONG                     Value);

DWORD PdhBrowseCounters(
  [in] HWND hwndParent,
  [in] PDH_BROWSE_COUNTERS_CONFIG *pConfig,
  [in] LPSTR *ppCounterPath
);

typedef struct _PDH_COUNTER_INFO_A {
  DWORD dwLength;
  DWORD dwType;
  DWORD CVersion;
  DWORD CStatus;
  LONG lScale;
  LONG lDefaultScale;
  DWORD_PTR dwUserData;
} PDH_COUNTER_INFO_A;

typedef struct _PDH_DATA_ITEM_PATH_ELEMENTS_W {
  LPWSTR szMachineName;
  GUID ObjectGUID;
  DWORD dwItemId;
  LPWSTR szInstanceName;
} PDH_DATA_ITEM_PATH_ELEMENTS_W, *PPDH_DATA_ITEM_PATH_ELEMENTS_W;

typedef struct _PDH_FMT_COUNTERVALUE {
DWORD CStatus;   union {
LONG     longValue;     double   doubleValue;     LONGLONG largeValue;
LPCSTR   AnsiStringValue;     LPCWSTR  WideStringValue;   };
} PDH_FMT_COUNTERVALUE, *PPDH_FMT_COUNTERVALUE;

typedef struct _PDH_RAW_COUNTER {
DWORD    CStatus;   FILETIME TimeStamp;   LONGLONG FirstValue;   LONGLONG SecondValue;   DWORD    MultiCount;
} PDH_RAW_COUNTER, *PPDH_RAW_COUNTER;

typedef struct _PDH_RAW_COUNTER_ITEM_A {
  LPSTR szName;
  PDH_RAW_COUNTER RawValue;
} PDH_RAW_COUNTER_ITEM_A, *PPDH_RAW_COUNTER_ITEM_A;

typedef struct _PDH_RAW_LOG_RECORD {
  DWORD dwStructureSize;
  DWORD dwRecordType;
  DWORD dwItems;
  UCHAR RawBytes[1];
} PDH_RAW_LOG_RECORD, *PPDH_RAW_LOG_RECORD;

成员说明：
dwStructureSize：结构体大小（字节），包含RawBytes数组。
dwRecordType：记录类型标识符。
dwItems：数据项数量。
RawBytes：原始数据缓冲区。

typedef struct _PDH_STATISTICS {
    DWORD dwFormat;
    DWORD count;
    PDH_FMT_COUNTERVALUE min;
    PDH_FMT_COUNTERVALUE max;
    PDH_FMT_COUNTERVALUE mean;
} PDH_STATISTICS, *PPDH_STATISTICS;

typedef struct _PDH_TIME_INFO {
LONGLONG StartTime;   LONGLONG EndTime;
DWORD    SampleCount;
} PDH_TIME_INFO, *PPDH_TIME_INFO;

typedef struct _PERF_COUNTER_DEFINITION {
  DWORD  ByteLength;
  DWORD  CounterNameTitleIndex;
  DWORD  CounterHelpTitleIndex;
  LONG   DefaultScale;
  DWORD  DetailLevel;
  DWORD  CounterType;
  DWORD  CounterSize;
  DWORD  CounterOffset;
} PERF_COUNTER_DEFINITION, *PPERF_COUNTER_DEFINITION;

typedef struct _PERF_COUNTER_REG_INFO {   ULONG     CounterId;
ULONG     Type;   ULONGLONG Attrib;
ULONG     DetailLevel;   LONG      DefaultScale;   ULONG     BaseCounterId;
ULONG     PerfTimeId;   ULONG     PerfFreqId;   ULONG     MultiId;
ULONG     AggregateFunc;   ULONG     Reserved;
} PERF_COUNTER_REG_INFO, *PPERF_COUNTER_REG_INFO;

typedef struct _PERF_COUNTERSET_INSTANCE {
  GUID CounterSetGuid;
  ULONG dwSize;
  ULONG InstanceId;
  ULONG InstanceNameOffset;
  ULONG InstanceNameSize;
} PERF_COUNTERSET_INSTANCE, *PPERF_COUNTERSET_INSTANCE;

typedef struct _PERF_COUNTERSET_REG_INFO {
  GUID CounterSetGuid;
  ULONG CounterSetType;
  ULONG DetailLevel;
  ULONG NumCounters;
  ULONG InstanceType;
} PERF_COUNTERSET_REG_INFO, *PPERF_COUNTERSET_REG_INFO;

typedef struct _PERF_DATA_HEADER {
    ULONG      dwTotalSize;
    ULONG      dwNumCounters;
    LONGLONG   PerfTimeStamp;
    LONGLONG   PerfTime100NSec;
    LONGLONG   PerfFreq;
    SYSTEMTIME SystemTime;
} PERF_DATA_HEADER, *PPERF_DATA_HEADER;

typedef struct _PROVIDER_CONTEXT {
DWORD          ContextSize;   DWORD          Reserved;
PERFLIBREQUEST ControlCallback;   PERF_MEM_ALLOC MemAllocRoutine;   PERF_MEM_FREE  MemFreeRoutine;   LPVOID         pMemContext;
} PERF_PROVIDER_CONTEXT, *PPERF_PROVIDER_CONTEXT;

ULONG PerfAddCounters(
  [in]      HANDLE                   hQuery,
  [in, out] PPERF_COUNTER_IDENTIFIER pCounters,
  [in]      DWORD                    cbCounters
);

typedef struct _PERF_COUNTER_DATA {
  ULONG dwDataSize;
  ULONG dwSize;
} PERF_COUNTER_DATA, *PPERF_COUNTER_DATA;

成员：
dwDataSize - PERF_COUNTER_DATA块中原始性能计数器数据的大小（字节）
dwSize - PERF_COUNTER_DATA结构体的大小（字节）

typedef struct _PERF_COUNTER_INFO {   ULONG     CounterId;
ULONG     Type;   ULONGLONG Attrib;   ULONG     Size;
ULONG     DetailLevel;
LONG      Scale;   ULONG     Offset;
} PERF_COUNTER_INFO, *PPERF_COUNTER_INFO;

typedef struct _PERF_COUNTER_IDENTIFIER {   GUID  CounterSetGuid;
ULONG Status;   ULONG Size;
ULONG CounterId;   ULONG InstanceId;   ULONG Index;
ULONG Reserved;
} PERF_COUNTER_IDENTIFIER, *PPERF_COUNTER_IDENTIFIER; 成员

typedef struct _PERF_COUNTER_IDENTITY {
    GUID CounterSetGuid;
    ULONG BufferSize;
    ULONG CounterId;
    ULONG InstanceId;
    ULONG MachineOffset;
    ULONG NameOffset;
    ULONG Reserved;
} PERF_COUNTER_IDENTITY, *PPERF_COUNTER_IDENTITY;

typedef struct _PERF_COUNTERSET_INFO {
  GUID CounterSetGuid;
  GUID ProviderGuid;
  ULONG NumCounters;
  ULONG InstanceType;
} PERF_COUNTERSET_INFO, *PPERF_COUNTERSET_INFO;

typedef struct _PERF_INSTANCE_HEADER {   ULONG Size;
ULONG InstanceId;
} PERF_INSTANCE_HEADER, *PPERF_INSTANCE_HEADER;

typedef struct _PERF_MULTI_COUNTERS {
  ULONG dwSize;
  ULONG dwCounters;
} PERF_MULTI_COUNTERS, *PPERF_MULTI_COUNTERS;

typedef struct _STRING_COUNTER_HEADER {
DWORD dwCounterId;   DWORD dwOffset;
} PERF_STRING_COUNTER_HEADER, *PPERF_STRING_COUNTER_HEADER;
成员 dwCounterId
性能计数器的标识符。 dwOffset
从 PERF_STRING_BUFFER_HEADER 块的开头到以 null 结尾的 UTF-16LE 数据的字节数。
值为 0xFFFFFFFF 表示字符串不存在;换句话说，字符串的值为 NULL。

ULONG PerfDeleteInstance(
[in] HANDLE                    Provider,
[in] PPERF_COUNTERSET_INSTANCE InstanceBlock);

ULONG PerfIncrementULongCounterValue(
[in] HANDLE                    Provider,   [in] PPERF_COUNTERSET_INSTANCE Instance,   [in] ULONG                     CounterId,
[in] ULONG                     Value);

ULONG PerfDeleteCounters(
  [in]      HANDLE                   hQuery,
  [in, out] PPERF_COUNTER_IDENTIFIER pCounters,
  [in]      DWORD                    cbCounters
);

ULONG PerfSetULongCounterValue(
[in] HANDLE                    Provider,   [in] PPERF_COUNTERSET_INSTANCE Instance,   [in] ULONG                     CounterId,
[in] ULONG                     Value);

ULONG PerfSetULongLongCounterValue(
[in] HANDLE                    Provider,   [in] PPERF_COUNTERSET_INSTANCE Instance,   [in] ULONG                     CounterId,
[in] ULONGLONG                 Value);

ULONG PerfSetCounterSetInfo(
[in] HANDLE                ProviderHandle,   [in] PPERF_COUNTERSET_INFO Template,
[in] ULONG                 TemplateSize);

typedef struct _PERF_OBJECT_TYPE {
  DWORD TotalByteLength;
  DWORD DefinitionLength;
  DWORD HeaderLength;
  DWORD ObjectNameTitleIndex;
  LPWSTR ObjectNameTitle;
  DWORD ObjectHelpTitleIndex;
  LPWSTR ObjectHelpTitle;
  DWORD DetailLevel;
  DWORD NumCounters;
  LONG DefaultCounter;
  LONG NumInstances;
  DWORD CodePage;
  LARGE_INTEGER PerfTime;
  LARGE_INTEGER PerfFreq;
} PERF_OBJECT_TYPE;

typedef struct _PERF_DATA_BLOCK {
  WCHAR Signature[4];
  DWORD LittleEndian;
  DWORD Version;
  DWORD Revision;
  DWORD TotalByteLength;
  DWORD HeaderLength;
  DWORD NumObjectTypes;
  LONG DefaultObject;
  SYSTEMTIME SystemTime;
  LARGE_INTEGER PerfTime;
  LARGE_INTEGER PerfFreq;
} PERF_DATA_BLOCK;
